/** Events */
export const events = {
	cloneProgress: makeEvent<CloneProgress>("clone-progress"),
	commandLogged: makeEvent<CommandLogged>("command-logged"),
	graphProgress: makeEvent<GraphProgress>("graph-progress"),
	journalChanged: makeEvent<JournalChanged>("journal-changed"),
	opFinished: makeEvent<OpFinished>("op-finished"),
	opProgress: makeEvent<OpProgress>("op-progress"),
	opStarted: makeEvent<OpStarted>("op-started"),
	ptyExited: makeEvent<PtyExited>("pty-exited"),
	ptyOutput: makeEvent<PtyOutput>("pty-output"),
	refsChanged: makeEvent<RefsChanged>("refs-changed"),
	scanProgress: makeEvent<ScanProgress>("scan-progress"),
	statusChanged: makeEvent<StatusChanged>("status-changed"),
};

/* Constants */
export const AUTO_FETCH_MAX_MINUTES = 240 as const;

export const AUTO_FETCH_MIN_MINUTES = 1 as const;

export const COMPARE_MAX_COMMITS = 1000 as const;

export const EDGE_MERGE = 1 as const;

export const EDGE_NORMAL = 0 as const;

export const EDGE_WIP = 2 as const;

export const FONT_SIZE_MAX = 18 as const;

export const FONT_SIZE_MIN = 11 as const;

export const GITIGNORE_PREVIEW_MAX = 50 as const;

export const GRAPH_COLORS = 8 as const;

export const GRAPH_FILTER_MAX = 1000 as const;

export const GRAPH_MAX_LANES = 48 as const;

export const GRAPH_PAGE_SIZE = 500 as const;

export const JOURNAL_PATHS_MAX = 20 as const;

export const REBASE_PLAN_MAX = 200 as const;

export const SCAN_DEPTH_MAX = 8 as const;

export const SCAN_DEPTH_MIN = 1 as const;

export const SIGNATURE_GPG = 1 as const;

export const SIGNATURE_NONE = 0 as const;

export const SIGNATURE_SSH = 2 as const;

export const SIGNATURE_UNKNOWN = 4 as const;

export const SIGNATURE_X509 = 3 as const;

export const WORKSPACE_NAME_MAX = 100 as const;

/* Types */
export type AppInfo = {
	/**  yaggui version, from `Cargo.toml`. */
	appVersion: string,
	/**  Version of the detected `git` binary (e.g. `2.43.0`), `None` if git was not found. */
	gitVersion: string | null,
	/**  `false` when the detected git is older than `min_git_version` (warning shown in the UI). */
	gitSupported: boolean,
	minGitVersion: string,
};

export type Blame = {
	path: string,
	/**  Commit blamed (full SHA), `None` for the working tree. */
	rev: string | null,
	content: BlameContent,
};

/**  Consecutive lines attributed to one commit. */
export type BlameChunk = {
	/**  First line, 0-based. */
	start: number,
	count: number,
	/**  Index in `commits`. */
	commit: number,
	/**  First line in the commit's version of the file, 0-based. */
	sourceStart: number,
};

/**  A commit lines are attributed to. */
export type BlameCommit = {
	/**  Null SHA (`000…`) for lines not committed yet. */
	sha: string,
	authorName: string,
	authorEmail: string,
	/**  Seconds since the Unix epoch. */
	authorTime: number | null,
	summary: string,
	/**  Path of the file in this commit. */
	path: string,
	/**  `None` for a root commit (or the boundary of a shallow clone). */
	previous: BlamePrevious | null,
	uncommitted: boolean,
};

export type BlameContent = { kind: "text"; lines: string[]; encoding: TextEncoding; commits: BlameCommit[]; 
/**  Sorted by `start`, covering every line once. */
chunks: BlameChunk[] } | 
/**  Not blamed: Git's line attribution means nothing on binary content. */
{ kind: "binary"; size: number | null } | 
/**  The file is not in HEAD yet (untracked or only added to the index). */
{ kind: "notCommitted" };

/**  Where the lines a commit introduced were before it, for "blame of the parent". */
export type BlamePrevious = {
	sha: string,
	path: string,
};

/**  What to blame. */
export type BlameRequest = {
	/**  Repository-relative path, in `rev` (or the working tree). */
	path: string,
	/**
	 *  Commit whose version is blamed; `None`: the working tree file, uncommitted lines
	 *  included.
	 */
	rev: string | null,
};

/**  Local branches the cleanup offers to delete, and the ones it leaves out. */
export type BranchCleanup = {
	/**  Branch the "merged" test uses (HEAD's), `None` when HEAD is detached or unborn. */
	into: string | null,
	/**  Merged or `[gone]` branches, sorted by name. */
	branches: CleanupBranch[],
	/**  Merged or `[gone]`, never offered: protected by the preferences. */
	protected: string[],
	/**  Merged or `[gone]`, never offered: checked out here or in another worktree. */
	checkedOut: string[],
};

/**  Where a new branch starts. */
export type BranchStart = { kind: "head" } | 
/**  A commit SHA (full or abbreviated). */
{ kind: "commit"; sha: string } | 
/**
 *  A full ref name: `refs/heads/…`, `refs/remotes/…` (tracked, as Git does by default)
 *  or `refs/tags/…`.
 */
{ kind: "ref"; fullName: string } | 
/**
 *  A stash, by `git stash branch`: the branch starts at the stash's base commit, is
 *  always checked out, gets the stash applied, and the stash is dropped when it applies.
 */
{ kind: "stash"; stash: StashId };

/**  One changed path of a diff target. */
export type ChangedFile = {
	/**  Repository-relative path, `/`-separated (the new path of a rename). */
	path: string,
	/**  Source path of a rename or copy. */
	oldPath: string | null,
	status: FileStatus,
	/**  Similarity of a rename or copy, 0–100. */
	similarity: number | null,
	/**  Added / removed lines. `None` for binary files, submodules and when stats were skipped. */
	additions: number | null,
	deletions: number | null,
	binary: boolean,
	oldMode: FileMode | null,
	newMode: FileMode | null,
};

export type ChangedFiles = {
	/**  Sorted by path. */
	files: ChangedFile[],
	/**  Line stats are not computed above `STATS_MAX_FILES` files (huge commits). */
	statsSkipped: boolean,
	/**
	 *  Paths of `files` stored with Git LFS (`filter=lfs`), sorted; their line stats are not
	 *  computed (F-262).
	 */
	lfs: string[],
};

/**  How `checkout` treats local changes. */
export type CheckoutMode = 
/**
 *  Refused with `dirtyWorktree` when tracked files have changes (staged or not); its
 *  payload tells whether `carry` would work.
 */
"clean" | 
/**
 *  Plain `git switch`: changes come along when they do not touch the files that differ
 *  between HEAD and the target; refused with `dirtyWorktree` otherwise.
 */
"carry" | 
/**
 *  Stash (untracked files included), check out, pop. A failed checkout pops the stash
 *  back; a conflicting pop keeps the stash and fails with `stashConflict`.
 */
"stashAndPop";

export type CheckoutResult = {
	/**  Branch now checked out (short name); `None` for a detached HEAD. */
	branch: string | null,
	/**  The local branch was created by this checkout (remote target). */
	created: boolean,
};

/**  What `checkout` moves HEAD to. */
export type CheckoutTarget = 
/**  A local branch, short name (`feat/graph`). */
{ kind: "branch"; name: string } | 
/**
 *  A remote-tracking branch, short name with its remote (`origin/feat/graph`): checks out
 *  the local branch of the same name, created to track it when missing (F-045).
 */
{ kind: "remote"; name: string } | 
/**  Any revision (SHA, tag…), checked out as a detached HEAD. */
{ kind: "detached"; rev: string };

export type CherryPickRequest = {
	/**
	 *  Commits to apply on HEAD (full or abbreviated SHAs), in any order: they are applied
	 *  in graph order, oldest first.
	 */
	commits: string[],
	/**
	 *  Parent number (1-based) to diff merge commits against (`-m`). Required when a merge
	 *  commit is picked (`mainlineRequired` otherwise).
	 */
	mainline: number | null,
};

/**  Why the cleanup lists a branch (F-105). */
export type CleanupBranch = {
	/**  Short name, `feat/x`. */
	name: string,
	sha: string,
	/**  Its tip is in the history of HEAD. */
	merged: boolean,
	/**  Its upstream is configured but no longer exists (`[gone]`); short name in `upstream`. */
	gone: boolean,
	upstream: string | null,
	/**
	 *  Commits only this branch reaches (not HEAD): what the deletion leaves to the reflog.
	 *  0 when merged.
	 */
	unmerged: number,
};

/**  Progress of a clone, which has no repository (and so no `op_id`) yet. */
export type CloneProgress = {
	cloneId: string,
	/**  Git phase as printed by Git, e.g. `Receiving objects` (not translated). */
	phase: string,
	/**  0–100 when Git reports a percentage. */
	percent: number | null,
	current: number | null,
	total: number | null,
};

export type CloneRequest = {
	/**  Chosen by the frontend; tags `clone-progress` events and targets `cancel_clone`. */
	cloneId: string,
	/**  HTTPS, SSH (`git@host:path`, `ssh://`) or local (`file://`, a path) address. */
	url: string,
	/**  Absolute path of the folder to create (or to fill, if it exists and is empty). */
	target: string,
	/**  Branch or tag to check out instead of the remote's default branch. */
	branch: string | null,
	/**  Shallow clone: number of commits kept. */
	depth: number | null,
	recurseSubmodules: boolean,
};

export type CloneResult = {
	/**  Worktree of the new repository, ready for `open_repo`. */
	path: string,
};

export type CommandLogEntry = {
	/**  Monotonic id, unique for the app run. */
	id: number,
	/**  Repository the command ran for, if any. */
	repoId: number | null,
	/**  Arguments after `git` (e.g. `["fetch", "--progress", "origin"]`). */
	args: string[],
	cwd: string | null,
	/**  Start time, seconds since the Unix epoch. */
	startedAt: number,
	durationMs: number,
	/**  Process exit code; `None` if killed or never started. */
	exitCode: number | null,
	status: CommandStatus,
	stdout: string,
	stderr: string,
	/**  `true` when stdout or stderr was cut to `MAX_OUTPUT_BYTES`. */
	truncated: boolean,
};

/**  A Git command finished (successfully or not) and was added to the command log. */
export type CommandLogged = {
	entry: CommandLogEntry,
};

export type CommandStatus = "success" | "failed" | "cancelled" | 
/**  The process could not be started (git missing, bad cwd…). */
"spawnFailed";

/**  Header of the commit detail panel. Files and diff come from the diff commands (M1-4). */
export type CommitDetail = {
	sha: string,
	parents: string[],
	summary: string,
	/**  Full message, summary included, without the trailing newline. */
	message: string,
	author: Signature,
	committer: Signature,
	/**  Refs pointing at this commit. */
	refs: RefLabel[],
	signature: SignatureKind | null,
	/**
	 *  Row in the current graph, when the commit is in it and the history walk already
	 *  reached it (use `graph_index_of` to wait for it).
	 */
	row: number | null,
};

/**  A commit message split the way the commit box shows it. */
export type CommitMessage = {
	summary: string,
	description: string,
};

/**  A commit as shown in a label: SHA and first line. */
export type CommitRef = {
	sha: string,
	summary: string,
};

export type CommitRequest = {
	/**  First line of the message; must not be empty. */
	summary: string,
	/**  Body, after a blank line; empty for none. */
	description: string,
	/**  Replace the HEAD commit (its message and content) instead of adding one. */
	amend: boolean,
	/**  `--no-verify`: skip the `pre-commit` and `commit-msg` hooks. Off by default in the UI. */
	skipHooks: boolean,
};

export type CommitResult = {
	/**  Full SHA of the new commit. */
	sha: string,
};

/**
 *  Criteria of a commit search (F-027). Every criterion given must match (AND); text
 *  comparisons ignore case.
 */
export type CommitSearch = {
	/**  Contained in the message or the author name/email, or a prefix of the SHA. */
	text: string | null,
	/**  Contained in the author name or email. */
	author: string | null,
	/**
	 *  Commit changes this file, or a file under this folder, compared to its first parent
	 *  (all paths for a root commit). Relative to the worktree root, `/` separators.
	 */
	path: string | null,
	/**  Author date lower bound, inclusive, seconds since the Unix epoch. */
	since: number | null,
	/**  Author date upper bound, inclusive, seconds since the Unix epoch. */
	until: number | null,
};

/**
 *  What the commit panel shows before a commit: the `commit.template` message and whether
 *  Git will sign.
 */
export type CommitSettings = {
	/**
	 *  Message of the `commit.template` file, comment lines removed. `None`: no template, or
	 *  unreadable (`template_error`).
	 */
	template: CommitMessage | null,
	/**  The configured path, as Git resolved it. */
	templatePath: string | null,
	/**  Why the configured template could not be read. */
	templateError: string | null,
	/**  `commit.gpgsign` is on: commits are signed with this format. */
	sign: SigningFormat | null,
	/**  `user.signingkey`, when set (a key id, or a path for SSH). */
	signingKey: string | null,
};

export type CommitSummary = {
	sha: string,
	summary: string,
	author: string,
};

/**  A commit message template written in yaggui (the one of `commit.template` is read from Git). */
export type CommitTemplate = {
	id: number | null,
	name: string,
	/**  Full message: summary line, blank line, description. */
	body: string,
};

/**  A commit with what a list of commits shows (branch comparison). */
export type ComparedCommit = {
	sha: string,
	summary: string,
	authorName: string,
	authorEmail: string,
	/**  Seconds since the Unix epoch. */
	authorTime: number | null,
	/**  Row in the current graph, `None` when it is not shown. */
	row: number | null,
};

/**  Two revisions compared (F-104): the commits of each side not in the other, newest first. */
export type Comparison = {
	/**  Full SHAs the revisions resolved to. */
	a: string,
	b: string,
	/**  Best common ancestor, `None` for unrelated histories. */
	mergeBase: string | null,
	/**  In `a`, not in `b` (at most `COMPARE_MAX_COMMITS`). */
	onlyA: ComparedCommit[],
	/**  In `b`, not in `a`. */
	onlyB: ComparedCommit[],
	/**  Totals, beyond the lists when they are cut. */
	onlyACount: number,
	onlyBCount: number,
	/**  Graph version the rows belong to. */
	version: number,
};

/**
 *  One `key = value` line of a config file. `value` is `None` for a bare key (`[core] bare`),
 *  which Git reads as `true`.
 */
export type ConfigEntry = {
	key: string,
	value: string | null,
};

/**  Where `set_git_identity` writes. */
export type ConfigScope = 
/**  The repository's `.git/config`. */
"repo" | 
/**  The user's `~/.gitconfig`. */
"global";

/**  Confirmation dialogs that can be turned off. */
export type ConfirmationKind = "discardChanges" | "deleteTag" | "dropStash" | 
/**  Always asked: listed so the screen can show it locked. */
"forcePush";

export type ConflictFile = {
	path: string,
	/**  `None` once resolved (Git no longer records how it was in conflict). */
	kind: ConflictKind | null,
	/**  One of the versions is binary: no line-by-line merge, choose a side (F-165). */
	binary: boolean,
	/**  Marked resolved (staged) since the operation stopped. */
	resolved: boolean,
};

/**  How a path is in conflict (index stages, as `git status` reports them). */
export type ConflictKind = 
/**  Changed on both sides (`UU`). */
"content" | 
/**  Added on both sides with different content (`AA`). */
"bothAdded" | 
/**  Deleted on our side, modified on theirs (`DU`). */
"deletedByUs" | 
/**  Modified on our side, deleted on theirs (`UD`). */
"deletedByThem" | 
/**  Only on our side, e.g. a rename against a deletion (`AU`). */
"addedByUs" | 
/**  Only on their side (`UA`). */
"addedByThem" | 
/**  Deleted on both sides, e.g. renamed differently (`DD`). */
"bothDeleted";

/**
 *  Who "ours" and "theirs" are in the current conflicts.
 *  - merge: ours = the current branch, theirs = the merged branch;
 *  - rebase: ours = the branch being rebased onto (with the commits already replayed),
 *    theirs = the commit being replayed, from the rebased branch;
 *  - cherry-pick: ours = the current branch, theirs = the picked commit;
 *  - revert: ours = the current branch, theirs = the reverted commit (its inverse applies);
 *  - stash apply/pop (no operation): ours = the current branch, theirs = no branch.
 */
export type ConflictLabels = {
	ours: SideLabel,
	theirs: SideLabel,
};

/**
 *  Conflicted files of the working tree (F-160), resolved ones included while the
 *  operation that stopped on them is in progress.
 */
export type ConflictList = {
	/**  Sorted by path. */
	files: ConflictFile[],
	unresolved: number,
	labels: ConflictLabels,
};

/**  How `resolve_conflicts` settles files. */
export type ConflictResolution = 
/**  Take our version (`checkout --ours`), or delete the file when our side deleted it. */
{ kind: "ours" } | 
/**  Take their version (`checkout --theirs`), or delete the file when their side did. */
{ kind: "theirs" } | 
/**
 *  Keep the working tree file as it is (edited by hand), or its absence: `git add` /
 *  `git rm`.
 */
{ kind: "markResolved" } | 
/**
 *  Write `content` (the result of the 3-way editor, UTF-8) then mark resolved. One path
 *  only.
 */
{ kind: "content"; content: string };

/**  One version of a conflicted file. */
export type ConflictSide = {
	/**  Blob id (index stage) or `None` for the working tree. */
	id: string | null,
	/**  Text, `None` when binary. Not UTF-8 text is decoded lossily. */
	text: string | null,
	binary: boolean,
	/**  Bytes, saturated at `u32::MAX` (specta refuses `u64`). */
	size: number,
};

/**  Index stage of a conflicted file. */
export type ConflictStage = "base" | "ours" | "theirs";

/**  Everything the 3-way merge editor (M3-3) needs for one file. */
export type ConflictVersions = {
	path: string,
	/**  `None` when the file is not (or no longer) in conflict. */
	kind: ConflictKind | null,
	/**  Common ancestor version (stage 1); `None` when absent there (add/add…). */
	base: ConflictSide | null,
	/**  Stage 2; `None` when our side deleted it. */
	ours: ConflictSide | null,
	/**  Stage 3; `None` when their side deleted it. */
	theirs: ConflictSide | null,
	/**  Working tree file, with conflict markers for a content conflict; `None` when absent. */
	merged: ConflictSide | null,
	labels: ConflictLabels,
};

export type CreateTagRequest = {
	name: string,
	/**  Commit (or any revision) to tag. */
	target: string,
	/**  Non-blank: annotated tag with this message. `None` or blank: lightweight tag. */
	message: string | null,
	/**  `-s`: GPG-signed annotated tag (needs a message). */
	sign: boolean,
};

export type CreateWorktreeRequest = {
	/**  Absolute path of the new worktree: a folder that does not exist yet, or an empty one. */
	path: string,
	branch: WorktreeBranch,
};

export type DeleteBranchRequest = {
	/**  Short name of the local branch. */
	name: string,
	/**  `-D`: delete even when not merged. Without it, `branchNotMerged` is returned. */
	force: boolean,
	/**  Also delete the branch on its upstream remote (`git push <remote> --delete`). */
	deleteRemote: boolean,
};

export type DeleteBranchResult = {
	local: DeletedRef,
	/**  `refs/remotes/<remote>/<branch>` as it was before the remote deletion, when done. */
	remote: DeletedRef | null,
	/**  The remote deletion failed (network, rights…) after the local branch was deleted. */
	remoteError: YagguiError | null,
};

export type DeleteBranchesResult = {
	/**  Each deleted branch and the commit it pointed to. */
	deleted: DeletedRef[],
};

/**  A deleted ref and where it pointed, for the undo (M4). */
export type DeletedRef = {
	fullName: string,
	sha: string,
};

export type Density = "comfortable" | "compact";

export type DiffContent = {
	kind: "text",
} & TextDiff | 
/**  Binary on at least one side: sizes only (`None` = side absent). */
({ kind: "binary"; oldSize: number | null; newSize: number | null }) & { lines?: never; new?: never; newCommit?: never; old?: never; oldCommit?: never } | 
/**  Above the size guards: not rendered unless asked (`DiffOptions::force`). */
({ kind: "tooLarge"; oldSize: number | null; newSize: number | null; 
/**  Lines the diff would render; `None` when the size alone stopped it (not loaded). */
lines: number | null }) & { new?: never; newCommit?: never; old?: never; oldCommit?: never } | 
/**
 *  A file stored with Git LFS: the pointers (or the local content), never a text diff
 *  of the pointer files (F-262). `None` = side absent.
 */
({ kind: "lfs"; old: LfsObject | null; new: LfsObject | null }) & { lines?: never; newCommit?: never; newSize?: never; oldCommit?: never; oldSize?: never } | 
/**  Submodule commit change. */
({ kind: "submodule"; oldCommit: string | null; newCommit: string | null }) & { lines?: never; new?: never; newSize?: never; old?: never; oldSize?: never } | 
/**  Merge conflict: shown by the conflict editor (M3). */
({ kind: "conflict" }) & { lines?: never; new?: never; newCommit?: never; newSize?: never; old?: never; oldCommit?: never; oldSize?: never };

/**  A contiguous block of changes with its context, as in `@@ -a,b +c,d @@`. */
export type DiffHunk = {
	/**  Stable within one file diff (`"-a,b+c,d"`), for hunk-level staging (M2). */
	id: string,
	/**  1-based first line on each side (0 when the side is empty, as in Git). */
	oldStart: number,
	oldLines: number,
	newStart: number,
	newLines: number,
	/**  Enclosing function or section, like the text after `@@` in `git diff`. */
	header: string,
	/**  One char per line: `' '` context, `'-'` removed, `'+'` added. */
	kinds: string,
	/**  Line contents, without line terminator. */
	lines: string[],
};

export type DiffOptions = {
	/**  Like `git diff -w`. */
	ignoreWhitespace: boolean,
	/**  Unchanged lines around each change. Ignored when `full_file` is set. */
	contextLines: number,
	/**  One hunk spanning the whole file. */
	fullFile: boolean,
	/**  Render even above the size guards (`DiffContent::TooLarge`). */
	force: boolean,
};

/**  Diff display options kept across sessions (F-082). */
export type DiffPreferences = {
	/**  Soft-wrap long lines. */
	wrap: boolean,
	/**  Like `git diff -w`. Hunk and line actions are disabled while it is on. */
	ignoreWhitespace: boolean,
	/**  Unchanged lines around each change. */
	contextLines: number,
	/**  One hunk spanning the whole file. */
	fullFile: boolean,
};

/**  Side of a file diff. */
export type DiffSide = "old" | "new";

/**  What to compare. */
export type DiffTarget = 
/**
 *  Changes introduced by `to` (a commit id or revision). `from` defaults to the first
 *  parent of `to` (the empty tree for a root commit). Merges are shown against their
 *  first parent, like GitKraken.
 */
{ kind: "commits"; from: string | null; to: string } | 
/**  HEAD → index (what the next commit will contain). */
{ kind: "staged" } | 
/**  Index → working tree, untracked files included. */
{ kind: "unstaged" };

export type DiffViewMode = "unified" | "split";

/**
 *  Number of changed paths, by kind, as the changes panel lists them (untracked files one by
 *  one, a rename once). A path staged and modified again counts in both.
 */
export type DirtyState = {
	staged: number,
	unstaged: number,
	untracked: number,
	conflicted: number,
};

/**  What a discard saved before touching the files, for the undo (M4). */
export type DiscardResult = {
	/**  Folder name of the backup under `<app config>/backups/`. */
	backupId: string,
};

/**  Suggested fix the UI can offer as a button next to the error. */
export type ErrorAction = 
/**  Add the path to the global `safe.directory` list (`add_safe_directory`), after confirmation. */
{ kind: "addSafeDirectory"; path: string } | 
/**  Remove a stale `index.lock` (`remove_stale_index_lock`), after confirmation. */
{ kind: "removeIndexLock"; repoId: number | null; path: string } | 
/**  Install Git or configure its path. */
{ kind: "installGit" } | 
/**  Open the command log to see the full Git output. */
{ kind: "openCommandLog" } | 
/**  Try the same action again. */
{ kind: "retry" } | 
/**  Choose the terminal to use (terminal preference). */
{ kind: "configureTerminal" } | 
/**  Set `user.name` / `user.email` (`set_git_identity`), then retry. */
{ kind: "configureIdentity"; repoId: number | null } | 
/**  Reload the file list and diffs, then redo the selection. */
{ kind: "refresh" } | 
/**  Redo the deletion with `force` (`delete_branch`), after confirmation. */
{ kind: "forceDelete" } | 
/**  Pull (default strategy), then push again. */
{ kind: "pullThenPush" } | 
/**  Push again with `setUpstream`, after confirmation. */
{ kind: "pushSetUpstream" };

/**  Stable machine-readable error code; the frontend switches on it, never on messages. */
export type ErrorCode = 
/**  The command exists in the contract but has no backend implementation yet. */
"notImplemented" | 
/**  The `git` binary could not be found or executed. */
"gitNotFound" | 
/**  The path does not exist. */
"repoNotFound" | 
/**  The path exists but is not inside a Git repository. */
"notARepository" | 
/**  Git refuses the repository because of `safe.directory` (owned by another user). */
"unsafeRepository" | 
/**  `.git/index.lock` exists: another Git process is running, or one crashed. */
"indexLocked" | 
/**  A path exceeds Windows' 260-character limit and `core.longpaths` is off. */
"pathTooLong" | 
/**  The repository id does not match an open repository session. */
"repoNotOpen" | 
/**  An unknown operation id was given. */
"opNotFound" | 
/**  The operation was cancelled by the user. */
"cancelled" | 
/**  A frontend-provided argument was rejected by validation. */
"invalidArgument" | 
/**  Reading or writing the local SQLite store failed. */
"storage" | 
/**  A Git command failed with an error not (yet) in the catalog. */
"gitFailed" | 
/**  Unexpected internal failure (bug, I/O error…). */
"internal" | 
/**  The repository is open but its files are not watched: no automatic refresh. */
"watchUnavailable" | 
/**  No terminal could be started (the configured one, or none of the defaults). */
"terminalNotFound" | 
/**  The external editor could not be started. */
"editorNotFound" | 
/**  The system file manager could not open the repository folder. */
"fileManagerFailed" | 
/**  The integrated terminal could not start a shell (no PTY, shell missing). */
"shellFailed" | 
/**  The integrated terminal session does not exist any more (shell exited, closed). */
"terminalClosed" | 
/**  An avatar could not be downloaded (offline, unexpected answer); nothing is cached. */
"avatarUnavailable" | 
/**  The configured Git path does not exist or is not Git. */
"gitBinaryInvalid" | 
/**  A SHA, branch or other revision does not exist in the repository. */
"revisionNotFound" | 
/**  Nothing staged to commit (and not an amend). */
"nothingToCommit" | 
/**  `user.name` / `user.email` are not configured: Git refuses to commit. */
"identityUnknown" | 
/**  A `pre-commit` / `commit-msg` hook rejected the commit; output in `payload`. */
"hookFailed" | 
/**  The file changed since its diff was shown: the hunk selection no longer applies. */
"staleDiff" | 
/**  Unmerged paths prevent the operation (resolve the conflicts first). */
"unresolvedConflicts" | 
/**  The operation needs a branch and HEAD is detached. */
"detachedHead" | 
/**  A branch or tag name refused by `git check-ref-format`. */
"invalidRefName" | 
/**  A branch or tag of that name already exists. */
"refExists" | 
/**  Local changes prevent the checkout; files and options in `payload`. */
"dirtyWorktree" | 
/**  `git branch -d` refuses: the branch is not merged (action: force). */
"branchNotMerged" | 
/**  The checked out branch cannot be deleted. */
"currentBranch" | 
/**  Applying a stash left conflicts; the stash is kept (`payload`). */
"stashConflict" | 
/**  No local change to stash. */
"nothingToStash" | 
/**  The refs (stash list…) changed since they were listed: refresh and retry. */
"staleRefs" | 
/**
 *  A merge, rebase, cherry-pick or revert (or the merge or rebase of a pull) stopped on
 *  conflicts and is now in progress (`payload`): resolve them, then continue, skip or
 *  abort.
 */
"conflicts" | 
/**  A merge commit is cherry-picked or reverted without choosing its parent (`mainline`). */
"mainlineRequired" | 
/**  The commit being applied brings no change any more (already applied): skip it. */
"emptyCommit" | 
/**  Continue, skip or abort while no operation is in progress. */
"noOperation" | 
/**  A merge, rebase, cherry-pick, revert or bisect is already in progress. */
"operationInProgress" | 
/**  No external merge tool is configured (`merge.tool`). */
"mergeToolMissing" | 
/**  The external merge tool could not be started (unknown or not installed). */
"mergeToolFailed" | 
/**  Push refused: the remote branch has commits the local one lacks (action: pull then push). */
"pushRejected" | 
/**  `--force-with-lease` refused: the remote branch moved since it was last fetched. */
"staleLease" | 
/**  Force push refused on a protected branch (the list is a preference). */
"protectedBranch" | 
/**  The remote refused the credentials, or none were available (no prompt is ever shown). */
"authFailed" | 
/**  The remote does not exist (no such remote, or no repository at its URL). */
"remoteNotFound" | 
/**  The remote host could not be reached (DNS, refused or timed out connection). */
"hostUnreachable" | 
/**  The branch has no upstream (pull, or push without `setUpstream`). */
"noUpstream" | 
/**  `--ff-only` pull or `fastForwardOnly` merge refused: the branches diverged. */
"notFastForward" | 
/**  The branch asked for does not exist on the remote. */
"remoteBranchNotFound" | 
/**  The folder to clone into already holds files. */
"targetNotEmpty" | 
/**  The folder already is a Git repository. */
"alreadyRepository" | 
/**  The branch is checked out in another worktree: Git refuses to check it out twice. */
"branchInOtherWorktree" | 
/**  `git worktree remove` refuses: the worktree has local changes (force to discard them). */
"worktreeDirty" | 
/**  The worktree is locked (`git worktree lock`): unlock it first. */
"worktreeLocked" | 
/**  The repository uses Git LFS and the `git lfs` command is not installed. */
"lfsNotInstalled" | 
/**  A remote of that name already exists. */
"remoteExists" | 
/**  A remote name refused by Git (`refs/remotes/<name>/…` must be a valid ref). */
"invalidRemoteName" | 
/**  The remote refused a tag: one of that name points elsewhere there, or a hook declined it. */
"tagRejected" | 
/**  `undo` with no operation to undo in this session. */
"nothingToUndo" | 
/**  `redo` with no undone operation (or an operation was journaled since). */
"nothingToRedo" | 
/**
 *  The operation cannot be undone or redone locally (push, fetch with prune, pull…);
 *  reason in `payload`.
 */
"undoBlocked" | 
/**
 *  Refs or files changed since the operation (in a terminal, or by an operation that is
 *  not journaled): undoing it would lose that change. What moved in `payload`.
 */
"undoDiverged" | 
/**
 *  Undoing (or redoing) would overwrite local changes; files in `payload`. Commit or
 *  stash them first.
 */
"undoWouldOverwrite" | 
/**
 *  Git could not sign the commit (`commit.gpgsign`): no key, a key whose passphrase no
 *  agent provides (yaggui never asks for it), or the signing program failed.
 */
"signingFailed" | 
/**  No external diff tool is configured (preference, `diff.tool` or `diff.guitool`). */
"diffToolMissing" | 
/**  The external diff tool could not be started (unknown or not installed). */
"diffToolFailed" | 
/**  A branch protected by the preferences is refused by a batch deletion. */
"protectedBranchDelete" | 
/**  The branch is checked out in a worktree: it cannot be deleted. */
"branchCheckedOut";

/**  Structured data attached to some errors, for a dedicated display. */
export type ErrorPayload = 
/**  Output of a failed commit whose hook rejected it (a runaway output keeps its beginning and end). */
{ kind: "hook"; 
/**  `pre-commit` or `commit-msg` when only one of them is installed. */
hook: string | null; 
/**  Exit code of `git commit` (Git does not report the hook's own code). */
exitCode: number | null; stdout: string; stderr: string; 
/**
 *  The middle of a very long output was dropped (marked `[...]`): its beginning and
 *  end are kept.
 */
truncated: boolean } | 
/**  Why a checkout refuses local changes. */
{ kind: "dirtyWorktree"; 
/**
 *  Changed files that the checkout would overwrite (empty when only `clean` refused
 *  them: `canCarry` is then true).
 */
paths: string[]; 
/**  `carry` would succeed. */
canCarry: boolean } | 
/**  Conflicts left by a stash apply or pop. */
{ kind: "stashConflict"; 
/**  Conflicted files, now in the working tree with conflict markers. */
paths: string[]; 
/**  The stash, kept in the list (`stash@{0}` after a stash-checkout-pop). */
stashSha: string; 
/**  The checkout of a stash-checkout-pop happened before the conflict. */
checkedOut: boolean } | 
/**  Why an undo or redo is refused (`undoBlocked`). */
{ kind: "undoBlocked"; reason: UndoBlock } | 
/**
 *  What changed since the operation (`undoDiverged`), or the local changes an undo or redo
 *  would overwrite (`undoWouldOverwrite`).
 */
{ kind: "undoChanges"; 
/**  Full ref names (`refs/heads/main`, `HEAD`). */
refs: string[]; 
/**  Repository-relative paths, sorted. */
paths: string[] } | 
/**  An operation stopped on conflicts. */
{ kind: "conflicts"; 
/**  The operation now in progress, as `repo_state` reports it. */
operation: RepoOperation | null; 
/**  Conflicted files, sorted. */
paths: string[] };

/**  Result of "Test" next to an external tool setting. */
export type ExternalToolCheck = {
	/**  The program that was started, or the tool Git knows. */
	tool: string,
	/**  Editor and terminal: started. Diff and merge tools: known to Git and installed. */
	ok: boolean,
	/**  Why a diff or merge tool is not usable. */
	issue: ToolIssue | null,
};

/**  What an external tool setting is for. */
export type ExternalToolKind = "editor" | "terminal" | "diffTool" | "mergeTool";

export type FetchTarget = { kind: "remote"; name: string } | { kind: "all" };

export type FileDiff = {
	path: string,
	oldPath: string | null,
	/**
	 *  Blob ids compared, so a hunk operation can check the diff is still current. A working
	 *  tree side has the id `git hash-object` gives it once loaded (`None` when absent, or not
	 *  loaded: binary, too large, submodule).
	 */
	oldId: string | null,
	newId: string | null,
	oldMode: FileMode | null,
	newMode: FileMode | null,
	content: DiffContent,
};

/**  Where the next page of a file history starts. */
export type FileHistoryCursor = {
	/**  Commit the walk of this name starts from (full SHA). */
	rev: string,
	/**  Name of the file in that part of the history. */
	path: string,
	/**  Entries of this name already returned. */
	skip: number,
};

/**  One commit that changed the file. */
export type FileHistoryEntry = {
	sha: string,
	parents: string[],
	authorName: string,
	authorEmail: string,
	/**  Seconds since the Unix epoch. */
	authorTime: number | null,
	summary: string,
	/**  Path of the file in this commit. */
	path: string,
	/**  Previous path when this commit renamed the file. */
	oldPath: string | null,
	/**  What the commit did to the file. A merge (no diff of its own) is `modified`. */
	status: FileStatus,
	/**  Similarity of a rename, 0–100. */
	similarity: number | null,
};

export type FileHistoryPage = {
	/**  Newest first. */
	entries: FileHistoryEntry[],
	/**  `None` at the start of the file's history. */
	next: FileHistoryCursor | null,
};

/**  Entry type of a path, from its Git mode. */
export type FileMode = 
/**  `100644` */
"regular" | 
/**  `100755` */
"executable" | 
/**  `120000` */
"symlink" | 
/**  `160000`, a submodule commit. */
"submodule";

export type FileStatus = "added" | "modified" | "deleted" | "renamed" | "copied" | 
/**  The entry type changed (file ↔ symlink ↔ submodule). */
"typeChanged" | "untracked" | "conflicted";

/**  What a force push of a branch would overwrite, for its confirmation. */
export type ForcePushPreview = {
	remote: string,
	remoteBranch: string,
	/**  Remote-tracking SHA (as of the last fetch); `None` if the branch is not on the remote. */
	remoteSha: string | null,
	/**  Commits on the remote branch that the push would drop (newest first, at most 100). */
	overwritten: CommitSummary[],
	/**  More than the listed commits would be dropped. */
	truncated: boolean,
	/**  Force push is refused on this branch. */
	protected: boolean,
};

/**  What yaggui knows about a `git` binary, for the preferences screen (F-322). */
export type GitBinaryInfo = {
	/**  Absolute path when it could be resolved, else what was asked for. */
	path: string | null,
	/**  `None` when the binary does not work (see `error`). */
	version: string | null,
	/**  `false` below the minimal supported version (warning in the UI). */
	supported: boolean,
	minVersion: string,
	error: YagguiError | null,
};

/**  `user.name` / `user.email` as Git resolves them for the repository. */
export type GitIdentity = {
	name: string | null,
	email: string | null,
};

/**  What adding a rule to `.gitignore` would do. */
export type GitignorePreview = {
	/**  The line to append. */
	rule: string,
	/**  The root `.gitignore` already has this line. */
	exists: boolean,
	/**  Untracked files the rule would hide (at most `GITIGNORE_PREVIEW_MAX`). */
	matches: string[],
	matchCount: number,
};

/**  Which rule "Add to .gitignore" writes for a file. */
export type GitignoreRuleKind = 
/**  This exact file (`/path/to/file`). */
"file" | 
/**  Every file with its extension (`*.log`). */
"extension" | 
/**  Its folder (`/path/to/`). */
"folder";

export type GitignoreTemplate = "node" | "rust" | "dotNet" | "python" | "macOs" | "windows";

/**
 *  Refs left out of the graph (F-028), kept per repository. HEAD's commit always stays,
 *  except in solo mode on another ref.
 */
export type GraphFilter = {
	/**
	 *  Full names of hidden branches and tags (`refs/heads/x`, `refs/remotes/origin/x`):
	 *  neither their tip nor their label is shown. Their commits stay when another ref
	 *  reaches them.
	 */
	hidden: string[],
	/**
	 *  Full name of the only ref whose history is shown. Ignored when that ref no longer
	 *  exists.
	 */
	solo: string | null,
	/**  Every remote-tracking branch hidden. */
	hideRemotes: boolean,
	/**  Stash labels hidden. */
	hideStashes: boolean,
};

/**  Result of `graph_index_of`. */
export type GraphLocation = {
	version: number,
	/**  Full SHA of the commit the revision resolved to. */
	sha: string,
	/**  `None` when the commit is not in the graph (not reachable from any ref or HEAD). */
	row: number | null,
};

/**
 *  A slice of the commit graph, rows `start .. start + shas.length`.
 * 
 *  Rows are commits only, in `git log --topo-order` order over every branch, remote branch,
 *  tag and HEAD (stashes are labels on their base commit, not rows). Without commit-graph, a
 *  commit with more than a year of unread history above it when Git would list it is placed
 *  by date instead (see `graph/topo.rs`); the order stays topological. The WIP node is not a
 *  row: it sits above row 0 (see `wip`), so row indices do not move when the worktree
 *  becomes dirty or clean.
 */
export type GraphPage = {
	/**
	 *  Identifies the graph layout. It changes when refs change (`refs-changed`): never mix
	 *  rows of different versions, drop the cached pages and refetch.
	 */
	version: number,
	start: number,
	/**
	 *  Number of commit rows of the whole graph. While the history walk runs (`totalExact`
	 *  false), a lower bound that grows with each page and `graph-progress` event: rows
	 *  already sent never move, only more come.
	 */
	totalRows: number,
	/**  `false` while `total_rows` is a lower bound. */
	totalExact: boolean,
	/**  Lanes used by the rows and edges of this page (≤ `GRAPH_MAX_LANES`). */
	laneCount: number,
	/**  `None` when HEAD is unborn, not in the graph, or not reached by the history walk yet. */
	wip: GraphWip | null,
	/**  Full SHA of each row. */
	shas: string[],
	/**  Full parent SHAs of each row, first parent first. */
	parents: string[][],
	/**  First line of the message. */
	summaries: string[],
	authorNames: string[],
	authorEmails: string[],
	/**  Author dates, seconds since the Unix epoch. */
	authorTimes: (number | null)[],
	/**  Committer dates, seconds since the Unix epoch. */
	commitTimes: (number | null)[],
	/**  Lane of the node of each row. */
	lanes: number[],
	/**  Color of the node of each row. */
	colors: number[],
	/**  Signature of each row, a `signature_code` value (unverified). */
	signatures: number[],
	/**
	 *  Lines to draw between row `i` and row `i + 1`, flattened by groups of 4 numbers
	 *  `[fromLane, toLane, color, kind]`: `fromLane` is at the height of row `i`, `toLane`
	 *  at the height of row `i + 1`. The edges of the page's row `k` (0-based within the
	 *  page) are `edges[4 * edgeOffsets[k] .. 4 * edgeOffsets[k + 1]]` (`edgeOffsets` has
	 *  one more element than there are rows). A line leaving the node of row `i` has
	 *  `fromLane == lanes[i]`; a line joining the node of row `i + 1` has
	 *  `toLane == lanes[i + 1]`.
	 */
	edgeOffsets: number[],
	edges: number[],
	/**  Ref labels of the rows of this page, sorted by row. */
	refs: GraphRef[],
};

/**
 *  Progress of the history walk behind the graph (M5-4), sent when a page went out before the
 *  walk was done: the number of rows grows until `exact`. Rows never move within a version.
 */
export type GraphProgress = {
	repoId: number,
	version: number,
	/**  Rows so far; the final count once `exact`. */
	totalRows: number,
	exact: boolean,
	/**  This version is dropped (commit dates misled the walk): reload the graph. */
	stale: boolean,
};

/**  A ref label placed on a graph row. */
export type GraphRef = {
	/**  Absolute row index. */
	row: number,
	label: RefLabel,
};

/**
 *  The WIP node drawn above row 0 when the worktree is dirty (F-022). Its line runs on
 *  `lane` down to `headRow`; the edges of that line have the kind `edge_kind::WIP`.
 */
export type GraphWip = {
	lane: number,
	color: number,
	/**  Row of the commit HEAD points to. */
	headRow: number,
};

export type HeadState = 
/**  HEAD points to a branch that has at least one commit. */
{ kind: "branch"; name: string; oid: string } | 
/**  HEAD points to a branch without commits yet (fresh `git init`). */
{ kind: "unborn"; name: string } | 
/**  HEAD points directly to a commit. */
{ kind: "detached"; oid: string };

/**  What a history operation did to HEAD. */
export type HistoryEffect = 
/**  Nothing to do: already up to date, HEAD unchanged. */
"upToDate" | 
/**  The branch moved forward without a new commit. */
"fastForward" | 
/**  New commits were created (merge, squash, rebased, picked or revert commits). */
"commits";

/**
 *  Result of an operation that ran to its end. An operation that stops on conflicts fails
 *  with `conflicts` instead (it is then in progress: see `repo_state().operation`).
 */
export type HistoryResult = {
	effect: HistoryEffect,
	/**  SHA of HEAD afterwards. */
	head: string,
	/**
	 *  SHA the moved branch (or detached HEAD) pointed to before, for the undo (M4). For a
	 *  continue or skip, before the operation started (`ORIG_HEAD`) when known.
	 */
	previousHead: string | null,
};

/**
 *  A selection of hunks (or lines) of one file diff, with what identifies that diff so a
 *  stale selection is refused (`staleDiff`) instead of applied to other content.
 */
export type HunkChange = {
	path: string,
	/**  Source of a rename (staged diffs only), as in `FileDiff::old_path`. */
	oldPath: string | null,
	/**  `FileDiff::old_id` / `new_id` of the diff the selection was made on. */
	oldId: string | null,
	newId: string | null,
	/**
	 *  Options of that diff: context lines and whole-file mode decide the hunk ids.
	 *  `ignore_whitespace` is refused (its hunks do not describe the real content).
	 */
	options: DiffOptions,
	hunks: HunkSelection[],
};

/**  Part of one hunk of a file diff. */
export type HunkSelection = {
	/**  `DiffHunk::id` of the diff the selection was made on. */
	id: string,
	/**
	 *  Indexes into the hunk lines (`DiffHunk::kinds`) of the `+`/`-` lines to include;
	 *  context lines are ignored. `None` takes the whole hunk.
	 */
	lines: number[] | null,
};

/**  A name / email pair the user can apply to a repo (`git config --local`). */
export type IdentityProfile = {
	/**  `None` when saving a new profile. */
	id: number | null,
	/**  Shown in the picker ("Personal", "Work"). */
	label: string,
	name: string,
	email: string,
};

export type ImportFailure = {
	path: string,
	error: YagguiError,
};

/**  Outcome of `import_repos`. */
export type ImportResult = {
	/**  Ids of the imported repos (new or already known), in the order of the request. */
	repoIds: number[],
	failed: ImportFailure[],
};

export type IndexLockState = {
	path: string,
	ageSecs: number,
	/**  Old enough (> 10 s) to be probably left over by a crashed process. */
	stale: boolean,
};

export type InitRequest = {
	/**  Absolute path of the folder; created if missing. */
	target: string,
	defaultBranch: string,
	gitignore: GitignoreTemplate[],
	readme: boolean,
};

export type InitResult = {
	path: string,
	/**  Files written next to `.git`; an existing `.gitignore` or README is never replaced. */
	createdFiles: string[],
};

/**  The commits of `base..HEAD` an interactive rebase would rewrite (F-142). */
export type InteractiveRebasePlan = {
	/**  The commit the rewritten ones are replayed on (excluded from the list). */
	base: CommitRef,
	/**  SHA of HEAD when the plan was read. */
	head: string,
	/**  Current branch (short name). */
	branch: string,
	/**  Upstream of the branch (`origin/main`), `None` when it has none. */
	upstream: string | null,
	/**  Oldest first, the order of the todo list. At most `REBASE_PLAN_MAX` commits. */
	commits: RebasePlanCommit[],
	/**
	 *  The range contains merge commits: `interactive_rebase` refuses it (yaggui does not
	 *  rebuild merges, `--rebase-merges`).
	 */
	hasMerges: boolean,
	/**  Number of `commits` already on the upstream. */
	pushed: number,
};

/**
 *  Result of `interactive_rebase`. A stop on conflicts fails with `conflicts` instead, like
 *  `rebase`.
 */
export type InteractiveRebaseResult = {
	effect: HistoryEffect,
	/**  SHA of HEAD afterwards (the edited commit when stopped). */
	head: string,
	/**  SHA of the branch before the rebase, for the undo (M4). */
	previousHead: string,
	/**  Stopped on an `edit` step: the rebase is in progress (`repo_state().operation`). */
	stopped: RebaseStop | null,
};

/**
 *  The undo journal of a repository changed (operation journaled, undone or redone):
 *  refetch `undo_state` / `op_history`.
 */
export type JournalChanged = {
	repoId: number,
};

/**  One operation of the session journal. */
export type JournalEntry = {
	/**  Unique within the repository session. */
	id: number,
	op: JournalOp,
	/**  When the operation finished, Unix time in milliseconds (`f64`: specta refuses `u64`). */
	at: number | null,
	/**  Undone, and not redone since. */
	undone: boolean,
	/**  Set for operations that can never be undone (push, fetch with prune, pull). */
	blocked: UndoBlock | null,
};

/**  A journaled operation, with what its label needs. The frontend writes the text (i18n). */
export type JournalOp = 
/**  A new commit. */
{ kind: "commit"; sha: string; summary: string } | 
/**  HEAD commit replaced by `commit` with `amend`. */
{ kind: "amend"; sha: string; summary: string } | 
/**  `branch`: the branch checked out, `None` for a detached HEAD on `sha`. */
{ kind: "checkout"; branch: string | null; sha: string } | { kind: "createBranch"; name: string } | 
/**  `remote`: its remote branch was deleted too (then not undoable: `published`). */
{ kind: "deleteBranch"; name: string; remote: boolean } | { kind: "renameBranch"; from: string; to: string } | { kind: "createTag"; name: string } | { kind: "deleteTag"; name: string } | { kind: "addRemote"; name: string } | { kind: "renameRemote"; from: string; to: string } | 
/**  Fetch and push URLs changed (`git remote set-url`). */
{ kind: "setRemoteUrls"; name: string } | 
/**  Its tracking branches and the upstreams on it come back with an undo. */
{ kind: "removeRemote"; name: string } | { kind: "merge"; source: string; mode: MergeMode } | { kind: "reset"; mode: ResetMode; target: string } | 
/**
 *  Discard of whole files or of hunks / lines. `paths`: the files touched (at most
 *  `JOURNAL_PATHS_MAX`), `count`: how many in total.
 */
{ kind: "discard"; paths: string[]; count: number } | { kind: "stashDrop"; message: string } | 
/**  `count`: commits picked. */
{ kind: "cherryPick"; count: number } | { kind: "revert"; sha: string } | 
/**  Push of a branch or tag, or deletion of a remote branch or tag (`delete`). */
{ kind: "push"; remote: string | null; name: string | null; delete: boolean } | 
/**  Push of every local tag to `remote`. Never undoable (`published`). */
{ kind: "pushTags"; remote: string } | 
/**  Fetch with prune (a plain fetch only moves remote-tracking branches: not journaled). */
{ kind: "fetch"; remote: string | null } | { kind: "pull" } | 
/**  `git worktree add` (M4-5). `branch`: checked out there, `None` for a detached HEAD. */
{ kind: "createWorktree"; path: string; branch: string | null } | { kind: "removeWorktree"; path: string; branch: string | null } | 
/**  `git lfs track`: `.gitattributes` changed. */
{ kind: "lfsTrack"; pattern: string } | 
/**  `git lfs pull`: never undoable (`downloaded`). */
{ kind: "lfsPull" } | 
/**  `git submodule update`; `count`: submodules asked for, 0 for all. Never undoable. */
{ kind: "updateSubmodules"; count: number } | 
/**  Stash of selected files (F-182). `paths` / `count` as for `Discard`. */
{ kind: "stashPush"; message: string; paths: string[]; count: number } | 
/**  A rule appended to the repository's `.gitignore` (F-069). */
{ kind: "gitignore"; rule: string } | 
/**
 *  Local branches deleted by the cleanup (F-105). `names`: at most `JOURNAL_PATHS_MAX`,
 *  `count`: how many in total.
 */
{ kind: "deleteBranches"; names: string[]; count: number };

export type KeybindingOverride = {
	/**  Stable action id (`tab.new`, `git.push`…). */
	action: string,
	/**  Shortcut in `Mod+Shift+K` notation; `None` removes the shortcut. */
	shortcut: string | null,
};

export type KeybindingsFile = {
	path: string,
	overrides: KeybindingOverride[],
	/**
	 *  The file could not be read as a whole, or entries were skipped: the screen shows it,
	 *  and the file stays untouched until the user saves a change.
	 */
	problem: string | null,
};

export type KnownRepo = {
	id: number,
	/**  Absolute path of the worktree root. */
	path: string,
	/**  Display name (folder name by default). */
	name: string,
	favorite: boolean,
	/**  Last time the repo was opened, seconds since the Unix epoch. */
	lastOpenedAt: number,
	/**  `false` when the folder no longer exists (moved or deleted). */
	exists: boolean,
};

/**  Values previously kept in `localStorage` (M0-1), imported once. */
export type LegacyPreferences = {
	theme: ThemePreference | null,
	locale: Locale | null,
};

/**  One side of a file stored with LFS. */
export type LfsObject = {
	/**
	 *  `sha256:…` id of the content, `None` for a working tree file that is the content
	 *  itself (not hashed: that would read the whole file).
	 */
	oid: string | null,
	/**  Size of the content in bytes. */
	size: number | null,
};

/**  Git LFS in this repository (F-262). */
export type LfsStatus = {
	/**  `git lfs version` output (`git-lfs/3.4.1 …`), `None` when `git lfs` is not installed. */
	version: string | null,
	/**  Patterns routed to LFS by the root `.gitattributes` (`*.psd`…), in file order. */
	patterns: string[],
	/**  Some attributes file of the repository mentions LFS (patterns may be in subfolders). */
	used: boolean,
};

/**  Line ending style of one side of a text diff. */
export type LineEnding = 
/**  No line break at all (empty or single-line file). */
"none" | "lf" | "crlf" | "mixed";

export type LocalBranch = {
	/**  Short name, `feat/graph`. */
	name: string,
	/**  `refs/heads/feat/graph`. */
	fullName: string,
	/**  Commit the branch points to. */
	sha: string,
	/**  Checked out in this worktree. */
	isHead: boolean,
	upstream: UpstreamState | null,
	/**  Row of `sha` in the graph of version `RepoRefs::graphVersion`, when known. */
	row: number | null,
};

export type Locale = "en" | "fr";

/**  A user-facing text provided in every supported language. */
export type LocalizedText = {
	en: string,
	fr: string,
};

/**  Why a file would lose content with a hard reset. */
export type LostChange = 
/**  Tracked file with staged or unstaged changes (or conflicted): they are discarded. */
"modified" | 
/**  Added to the index since HEAD and absent from the target: the file is deleted. */
"added" | 
/**  Deleted locally (staged or not): the file comes back with the target's content. */
"deleted" | 
/**  Untracked file that the target tracks: it is overwritten. */
"untracked";

export type LostFile = {
	path: string,
	change: LostChange,
};

/**
 *  How `merge` integrates the other branch. Chosen for each merge (F-140), never read from
 *  the `merge.ff` configuration.
 */
export type MergeMode = 
/**  `--ff`: fast-forward when possible, merge commit otherwise. */
"fastForward" | 
/**  `--ff-only`: refused with `notFastForward` when a merge commit would be needed. */
"fastForwardOnly" | 
/**  `--no-ff`: always a merge commit. */
"noFastForward" | 
/**  `--squash`, then a regular (single-parent) commit of the result. */
"squash";

export type MergeRequest = {
	/**
	 *  What to merge into the current branch: a branch short name (`feat/x`, `origin/feat/x`),
	 *  a full ref name or a commit SHA.
	 */
	source: string,
	mode: MergeMode,
	/**
	 *  Message of the merge (or squash) commit. `None` or blank: Git's default
	 *  (`Merge branch 'feat/x'`, the squashed commits list).
	 */
	message: string | null,
};

/**  Outcome of the external merge tool. */
export type MergeToolResult = {
	/**
	 *  The file is resolved (the tool saved it and Git staged it); `false` when the tool was
	 *  closed without resolving it.
	 */
	resolved: boolean,
};

/**  Starting values of the clone and init dialogs. */
export type NewRepoDefaults = {
	/**  Folder used last for a clone or an init, if it still exists. */
	parentDir: string | null,
	/**  `init.defaultBranch` of the Git configuration, else `main`. */
	defaultBranch: string,
};

/**  An operation finished; the frontend should refresh what it touched. */
export type OpFinished = {
	repoId: number,
	opId: number,
	kind: OpKind,
	outcome: OpOutcome,
};

/**  Family of a queued write operation, used for labels and tab indicators. */
export type OpKind = "fetch" | "pull" | "push" | "checkout" | "commit" | 
/**  Stage or unstage files, hunks or lines. */
"stage" | 
/**  Discard working tree (and optionally staged) changes, after a backup. */
"discard" | "stash" | 
/**  Create, rename or delete a branch, or change its upstream. */
"branch" | 
/**  Create or delete a tag. */
"tag" | 
/**  Add, rename or remove a remote, or change its URLs. */
"remote" | "merge" | "rebase" | "cherryPick" | "revert" | "reset" | 
/**  Continue, skip or abort of a `git bisect` (bisect reset). */
"bisect" | 
/**  Continue, skip or abort of a `git am` stopped on a patch. */
"applyMailbox" | 
/**  External merge tool (`git mergetool`) on a conflicted file. */
"mergeTool" | 
/**  Repository maintenance (remove a lock, config change…). */
"maintenance" | 
/**  Initialize or update submodules. */
"submodule" | 
/**  Add, remove or prune worktrees. */
"worktree" | 
/**  Git LFS: download the objects of the checkout, track a pattern. */
"lfs" | 
/**
 *  Edit of the Git configuration from the preferences (F-325); not tied to a repository
 *  when the scope is global (`repo_id` 0).
 */
"config" | 
/**  Background write of the commit-graph; silent in the UI, reloads the graph when done. */
"commitGraph" | 
/**  Undo of a journaled operation. */
"undo" | 
/**  Redo of an undone operation. */
"redo";

/**  How a success should read when Git reports success for something that did not complete. */
export type OpNote = 
/**  A continue, skip or interactive rebase that halted on the next stop (`edit`). */
"paused" | 
/**  An abort of the operation in progress. */
"aborted";

export type OpOutcome = 
/**  `note`: the operation succeeded but did not complete what it started (see `OpNote`). */
{ kind: "success"; note: OpNote | null } | { kind: "failed"; error: YagguiError } | { kind: "cancelled" };

/**  Progress of a running operation, parsed from `git --progress` output. */
export type OpProgress = {
	repoId: number,
	opId: number,
	/**  Git phase as printed by Git, e.g. `Receiving objects` (not translated). */
	phase: string,
	/**  0–100 when Git reports a percentage. */
	percent: number | null,
	current: number | null,
	total: number | null,
	/**  Bytes transferred so far (network phases). `f64` on the wire: specta refuses `u64`. */
	bytes: number | null,
	/**  Transfer rate in bytes per second. */
	bytesPerSec: number | null,
};

/**  A write operation left the queue and started running. */
export type OpStarted = {
	repoId: number,
	opId: number,
	kind: OpKind,
	/**  Whether `cancel_op` has an effect on this operation. */
	cancellable: boolean,
};

/**  Details of the operation in progress, for its banner (F-146) and the continue dialog. */
export type OperationDetail = {
	operation: RepoOperation,
	labels: ConflictLabels,
	/**
	 *  Message Git prepared for the commit `continue_operation` creates (merge, squash,
	 *  cherry-pick, revert, rebase step), without its `#` comment lines. Pre-fills the
	 *  continue dialog. `None` when the operation creates no commit (bisect).
	 */
	message: string | null,
	/**  Files still in conflict. */
	unresolved: number,
	/**
	 *  `continue_operation` is possible now: no unresolved conflict and something to
	 *  continue (always `false` for bisect).
	 */
	canContinue: boolean,
	/**  `skip_operation` is meaningful (rebase, cherry-pick, revert, mailbox, bisect). */
	canSkip: boolean,
};

/**  Paths a file-level command applies to. */
export type PathSelection = 
/**  Every changed path of the list the command works on. */
{ kind: "all" } | 
/**  Repository-relative, `/`-separated paths, as listed by `changed_files`. */
{ kind: "paths"; paths: string[] };

export type Preferences = {
	theme: ThemePreference,
	/**  Visual style (F-320). */
	style: ThemeStyle,
	/**  `None` follows the OS language. */
	locale: Locale | null,
	/**
	 *  Terminal opened by "Terminal" (F-266): an application name on macOS (`iTerm`), a
	 *  program name or path elsewhere. `None` uses the system default.
	 */
	terminal: string | null,
	/**  What the Terminal button opens: the integrated panel (F-267) or the external terminal. */
	terminalMode: TerminalMode,
	/**  External editor (F-323): an application name on macOS, a program name or path elsewhere. */
	editor: string | null,
	/**  External diff tool (F-323): a name known to `git difftool`; `None` follows `diff.tool`. */
	diffTool: string | null,
	/**  External merge tool (F-323): a name known to `git mergetool`; `None` follows `merge.tool`. */
	mergeTool: string | null,
	/**  Diff layout (F-080). */
	diffView: DiffViewMode,
	/**  Diff display options (F-082). */
	diffOptions?: DiffPreferences,
	/**  Stronger borders and text contrast (F-320). */
	highContrast: boolean,
	density: Density,
	/**  Font family of the interface; `None` keeps the bundled one. */
	uiFont: string | null,
	/**  Font family of code and diffs; `None` keeps the bundled one. */
	codeFont: string | null,
	/**  Base text size in px, within `FONT_SIZE_RANGE`. */
	fontSize: number,
	/**  Path of the `git` binary (F-322); `None` uses the one found on the `PATH`. */
	gitPath: string | null,
	/**  Fetch every repository in the background (F-324). */
	autoFetch: boolean,
	/**  Minutes between two automatic fetches, within `AUTO_FETCH_RANGE`. */
	autoFetchMinutes: number,
	/**  Remove remote-tracking branches deleted on the remote when fetching. */
	prune: boolean,
	/**
	 *  Strategy of a pull that names none; `None` follows the Git configuration (`pull.rebase`,
	 *  `pull.ff`).
	 */
	pullStrategy: PullStrategy | null,
	/**  Branch names or patterns (`release/*`) that destructive operations treat with care. */
	protectedBranches: string[],
	/**  Confirmations the user turned off. `ForcePush` is never honored. */
	disabledConfirmations: ConfirmationKind[],
	/**
	 *  Gravatar avatars in the graph (F-033). Off by default: when on, the hash of each
	 *  author e-mail is sent to gravatar.com.
	 */
	gravatar?: boolean,
};

/**  The shell of an integrated terminal exited (or was closed); sent after its last output. */
export type PtyExited = {
	ptyId: number,
	/**  `None` when the exit status is unknown (killed by a signal, or not reaped in time). */
	exitCode: number | null,
};

/**  A started terminal. */
export type PtyInfo = {
	ptyId: number,
	/**  The shell that was started (`/bin/zsh`, `pwsh.exe`…), for the tab title. */
	shell: string,
};

/**
 *  Output of an integrated terminal (F-267), batched: at most one event every few
 *  milliseconds per terminal. `data` is UTF-8; a character split across two reads is sent
 *  whole with the second.
 */
export type PtyOutput = {
	ptyId: number,
	data: string,
};

export type PullResult = {
	/**  The strategy used (the configured default when none was given). */
	strategy: PullStrategy,
	/**  HEAD did not move. */
	upToDate: boolean,
};

export type PullStrategy = "ffOnly" | "merge" | "rebase";

export type PushRequest = {
	/**  Local branch to push; `None` for the checked out one. */
	branch: string | null,
	/**
	 *  When the branch has no upstream: push to `remote` (default `origin`) and set it
	 *  (`-u`). Without it, `noUpstream` is returned.
	 */
	setUpstream: boolean,
	remote: string | null,
	/**  `--force-with-lease`, refused on protected branches (`protectedBranch`). */
	forceWithLease: boolean,
	/**
	 *  SHA the remote branch must still point to (the one the confirmation showed);
	 *  `None`: its remote-tracking ref.
	 */
	expectedSha: string | null,
};

export type PushResult = {
	remote: string,
	/**  Short name of the branch on the remote. */
	remoteBranch: string,
	upstreamSet: boolean,
	/**  Nothing was sent: the remote branch already pointed there. */
	upToDate: boolean,
};

/**  What happens to a commit in an interactive rebase (F-142). */
export type RebaseAction = 
/**  Keep the commit as it is. */
"pick" | 
/**  Keep its changes with a new message (`RebaseTodoEntry::message`, required). */
"reword" | 
/**
 *  Meld into the previous kept commit, combining the messages: the group's message is
 *  the `message` of its last `squash` entry (required there).
 */
"squash" | 
/**  Meld into the previous kept commit, keeping that commit's message. */
"fixup" | 
/**  Remove the commit. */
"drop" | 
/**
 *  Apply the commit then stop: the rebase stays in progress (amend, add commits…), then
 *  `continue_operation` / `skip_operation` / `abort_operation`.
 */
"edit";

/**  A commit of the range an interactive rebase rewrites. */
export type RebasePlanCommit = {
	sha: string,
	summary: string,
	/**  Full message, to pre-fill a reword or a squash. */
	message: string,
	authorName: string,
	authorEmail: string,
	/**  Author time, seconds since the Unix epoch. */
	authorTime: number | null,
	/**  A merge commit: the interactive rebase is refused (`hasMerges`). */
	merge: boolean,
	/**  Already on the upstream branch: rewriting it means a force push. */
	pushed: boolean,
};

export type RebaseRequest = {
	/**
	 *  Local branch to rebase (short name). `None`: the current branch. Another branch is
	 *  checked out first, as `git rebase <onto> <branch>` does, and stays checked out.
	 */
	branch: string | null,
	/**  Where its commits are replayed: branch short name, full ref name or commit SHA. */
	onto: string,
};

/**  Where an interactive rebase stopped on an `edit` step. */
export type RebaseStop = {
	/**  The commit just applied (HEAD), to amend or build on. */
	commit: CommitRef,
	/**  1-based step and number of steps, as in `RepoOperation::Rebase`. */
	step: number | null,
	total: number | null,
};

/**  One line of the todo list, oldest commit first. */
export type RebaseTodoEntry = {
	/**  Full SHA, as listed by `interactive_rebase_plan`. */
	sha: string,
	action: RebaseAction,
	/**
	 *  New message (summary, blank line, body) for `reword`, and for the last `squash` of a
	 *  group: the message of the combined commit. Ignored for other actions. Kept verbatim,
	 *  lines starting with `#` included; no editor is ever opened.
	 */
	message: string | null,
};

export type RecentCommitMessage = {
	message: string,
	/**  Unix time, milliseconds. */
	usedAt: number | null,
};

/**  What a ref label designates. */
export type RefKind = 
/**  Detached HEAD (when HEAD is on a branch, the branch label has `isHead`). */
"head" | "localBranch" | "remoteBranch" | "tag" | "stash";

/**  A ref pointing at a commit, as shown on the graph and in the commit header (F-023). */
export type RefLabel = {
	kind: RefKind,
	/**  Short name: `main`, `origin/main`, `v1.2.0`, `stash@{0}`, `HEAD`. */
	name: string,
	/**  Full name: `refs/heads/main`, `refs/stash`… (`HEAD` for a detached HEAD). */
	fullName: string,
	/**  Local branch checked out in this worktree. */
	isHead: boolean,
	/**
	 *  Local branches: short name of the upstream (`origin/main`), to merge the local and
	 *  remote labels when both point at the same commit.
	 */
	upstream: string | null,
};

/**  Kind of ref a name is checked for (`validate_ref_name`). */
export type RefNameKind = "branch" | "tag";

/**  One move of the reference. */
export type ReflogEntry = {
	/**  `n` of `<ref>@{n}`: 0 is the latest move. */
	index: number,
	/**  Where the reference pointed after the move (full SHA). */
	newSha: string,
	/**  Where it pointed before; `None` when it was created by this move. */
	oldSha: string | null,
	/**  As written by Git: `commit: …`, `checkout: moving from a to b`, `reset: moving to …`. */
	message: string,
	committerName: string,
	/**  Seconds since the Unix epoch. */
	time: number | null,
	/**  `false` when the commit is gone (pruned): it cannot be restored. */
	exists: boolean,
};

export type ReflogPage = {
	/**  Full name of the reference: `HEAD` or `refs/heads/<branch>`. */
	reference: string,
	/**  Newest first. */
	entries: ReflogEntry[],
	/**  Entries in the whole reflog. */
	total: number,
};

/**  HEAD or refs changed (debounced): refetch branches, graph and `repo_state`. */
export type RefsChanged = {
	repoId: number,
};

export type RemoteBranch = {
	/**  Short name including the remote, `origin/main`. */
	name: string,
	/**  `refs/remotes/origin/main`. */
	fullName: string,
	sha: string,
	row: number | null,
};

/**  A configured remote and its remote-tracking branches (symbolic `origin/HEAD` excluded). */
export type RemoteRefs = {
	name: string,
	/**  Fetch URL, `None` for a remote without URL or branches left from a removed remote. */
	url: string | null,
	/**  `remote.<name>.pushurl` when set: pushes go there instead of `url`. */
	pushUrl: string | null,
	branches: RemoteBranch[],
};

/**  What removing a remote takes away, for its confirmation. Read-only. */
export type RemoteRemovalPreview = {
	/**  Remote-tracking branches deleted with it (`origin/main`), sorted. */
	tracking: string[],
	/**  Local branches whose upstream is on this remote: they lose their upstream. */
	upstreamOf: string[],
};

/**  A removed remote, with what is needed to add it back (undo). */
export type RemovedRemote = {
	name: string,
	url: string | null,
	pushUrl: string | null,
	/**  Its remote-tracking refs and where they pointed. */
	tracking: DeletedRef[],
};

/**  An open repository, as returned by `open_repo`. */
export type RepoInfo = {
	/**  Stable id (persisted), used by every repo-scoped command and event. */
	id: number,
	/**  Absolute path of the worktree root. */
	path: string,
	name: string,
	state: RepoState,
	/**
	 *  Set (code `watchUnavailable`) when the repository could not be watched: no
	 *  `status-changed` / `refs-changed` events, the UI must offer a manual refresh.
	 */
	watchError: YagguiError | null,
};

export type RepoOperation = 
/**
 *  `MERGE_HEAD` present, or a `--squash` merge whose commit is still to be made
 *  (`SQUASH_MSG`, Git keeps no other trace of it).
 */
{ kind: "merge"; squash: boolean } | { kind: "rebase"; 
/**
 *  Git ≥ 2.26 runs plain rebases through the interactive machinery, so this is
 *  also `true` for most non-interactive rebases; only a hint.
 */
interactive: boolean; 
/**  1-based index of the step being applied, when known. */
step: number | null; total: number | null; 
/**  Branch being rebased, when known (`feature/x`). */
headName: string | null } | { kind: "cherryPick" } | { kind: "revert" } | { kind: "bisect" } | 
/**  `git am` / mailbox apply. */
{ kind: "applyMailbox" };

/**  One row of the workspace overview (F-008). */
export type RepoOverview = { kind: "ready"; state: RepoState; 
/**
 *  Last fetch (modification of `FETCH_HEAD`), seconds since the Unix epoch; `None`
 *  if the repo was never fetched.
 */
lastFetchedAt: number | null } | 
/**  The folder is gone, or no longer holds a repository (F-009). */
{ kind: "missing" } | { kind: "failed"; error: YagguiError };

/**  Everything shown in the refs sidebar, in display order (names sorted). */
export type RepoRefs = {
	/**
	 *  Graph version the `row` fields refer to; `None` when the graph of the current refs
	 *  is not computed yet (every `row` is then `None`: use `graph_index_of`).
	 */
	graphVersion: number | null,
	head: HeadState,
	local: LocalBranch[],
	remotes: RemoteRefs[],
	tags: TagRef[],
	stashes: StashRef[],
	submodules: SubmoduleRef[],
	worktrees: WorktreeRef[],
};

export type RepoState = {
	head: HeadState,
	/**  `None` when HEAD is detached/unborn or the branch has no upstream. */
	upstream: UpstreamState | null,
	dirty: DirtyState,
	operation: RepoOperation | null,
	indexLock: IndexLockState | null,
};

export type ResetMode = 
/**  Only the branch moves; index and working tree keep their content (all staged). */
"soft" | 
/**  The branch and the index move; the working tree keeps its content (unstaged). */
"mixed" | 
/**
 *  Branch, index and working tree all take the target's content: local changes are lost
 *  (saved first in a backup, see `ResetResult::backup_id`).
 */
"hard";

/**  What a reset to a target would do, for the confirmation dialog (F-145). */
export type ResetPreview = {
	/**  Full SHA of the target. */
	target: string,
	/**  Branch that moves, `None` when HEAD is detached. */
	branch: string | null,
	/**  Commits of the branch that would no longer be on it (still in the reflog). */
	commitsLeftBehind: number,
	/**  Commits the branch would gain (the target is ahead of it). */
	commitsGained: number,
	/**
	 *  Files whose local content a `hard` reset loses (`soft` and `mixed` lose nothing).
	 *  Sorted by path.
	 */
	hardLost: LostFile[],
};

export type ResetRequest = {
	/**  Commit the current branch (or detached HEAD) is moved to. */
	target: string,
	mode: ResetMode,
};

export type ResetResult = {
	previousHead: string,
	head: string,
	/**
	 *  Backup of the files a hard reset overwrote (`<app config>/backups/<id>`), like a
	 *  discard; `None` when nothing was lost.
	 */
	backupId: string | null,
};

export type RevertRequest = {
	/**  Commit to revert (full or abbreviated SHA). */
	commit: string,
	/**
	 *  For a merge commit, the parent (1-based) whose side is kept (`-m`): 1 = the branch
	 *  the merge was made on. Required for a merge (`mainlineRequired`), refused otherwise.
	 */
	mainline: number | null,
};

/**  Progress of a folder scan (F-007), at most every 100 ms. */
export type ScanProgress = {
	scanId: string,
	/**  Folders explored so far. */
	visited: number,
	/**  Repositories found so far. */
	found: number,
	/**  Folder being explored. */
	current: string,
};

export type ScanRequest = {
	/**  Chosen by the frontend; tags `scan-progress` events and targets `cancel_scan`. */
	scanId: string,
	/**  Absolute path of the folder to explore. */
	root: string,
	/**  How many folder levels below the root are explored, within `SCAN_DEPTH_RANGE`. */
	maxDepth: number,
};

export type ScanResult = {
	/**  Sorted by path. */
	repos: ScannedRepo[],
	/**  Folders explored. */
	visited: number,
	/**  The scan stopped at `SCAN_MAX_RESULTS` repositories. */
	truncated: boolean,
};

export type ScannedRepo = {
	/**  Worktree root, as `open_repo` would store it. */
	path: string,
	name: string,
	/**  Id of the known repo at this path, if it is already in the list. */
	knownId: number | null,
};

/**
 *  One chunk of search results. A search scans the rows in order and stops after a
 *  short time budget: call again with `nextRow` until it is `None`. Cancelling is just not
 *  asking for the next chunk.
 */
export type SearchChunk = {
	/**
	 *  Graph version the row indices refer to. If it differs from the version of the
	 *  first chunk, the graph changed: restart the search.
	 */
	version: number,
	/**  Matching rows found in this chunk, ascending. */
	matches: number[],
	/**  Where to continue, `None` when the whole graph was scanned. */
	nextRow: number | null,
	/**  Rows known when this chunk was scanned (grows while the history walk runs). */
	totalRows: number,
};

/**
 *  One side of a conflict, described by what the UI shows instead of "ours" / "theirs"
 *  (F-163): a branch name when one is known, otherwise the commit.
 */
export type SideLabel = {
	/**  Short branch name (`main`, `origin/feat/x`), or `None` (detached, unknown commit). */
	branch: string | null,
	commit: CommitRef | null,
};

/**  Author or committer of a commit. */
export type Signature = {
	name: string,
	email: string,
	/**  Seconds since the Unix epoch. */
	time: number | null,
	/**  Time zone offset of the signature, in minutes east of UTC. */
	offsetMinutes: number,
};

export type SignatureCheck = {
	status: SignatureStatus,
	/**  `%GS`: who signed, as the key or allowed signers file names them. */
	signer: string | null,
	/**  `%GK`: key id or fingerprint. */
	key: string | null,
	/**  Why it could not be verified (first line of the verifier's error). */
	reason: string | null,
};

/**  Kind of cryptographic signature attached to a commit (not verified yet, see F-066). */
export type SignatureKind = "gpg" | "ssh" | "x509" | "unknown";

/**  Result of checking a commit signature (`%G?`). */
export type SignatureStatus = 
/**  No signature. */
"unsigned" | 
/**  Good signature from a trusted key (`G`). */
"verified" | 
/**
 *  Good signature, but the key is not known to be the author's (`U`), or it cannot be
 *  checked here (`E`: missing key, `N` with a signature: no `gpg.ssh.allowedSignersFile`).
 */
"unverified" | 
/**  Good signature made by a key or with a signature that has expired (`X`, `Y`). */
"expired" | 
/**  Signature made by a revoked key (`R`). */
"revoked" | 
/**  The signature does not match the commit (`B`). */
"bad";

/**  How Git signs commits in this repository (`gpg.format`). */
export type SigningFormat = "openpgp" | "ssh" | "x509";

/**  A stash commit and its message: what `git stash store` needs to restore it (undo). */
export type StashEntryInfo = {
	sha: string,
	message: string,
};

/**
 *  A stash entry as listed by `list_refs`. The SHA guards against a list that changed since
 *  (`staleRefs`): a stale index never applies or drops another stash.
 */
export type StashId = {
	/**  `StashRef::index` (0 = `stash@{0}`). */
	index: number,
	/**  `StashRef::sha`. */
	sha: string,
};

/**  `git stash push -- <paths>` (F-182). */
export type StashPathsRequest = {
	/**  Files to stash, staged and unstaged changes alike. */
	paths: string[],
	message: string | null,
	/**  Also stash the selected untracked files (otherwise they are left alone). */
	includeUntracked: boolean,
};

export type StashPushRequest = {
	/**  Stash message; `None` or blank for Git's `WIP on <branch>: …`. */
	message: string | null,
	/**  `--include-untracked`. */
	includeUntracked: boolean,
	/**  `--keep-index`: staged changes also stay in the index and working tree. */
	keepIndex: boolean,
};

export type StashRef = {
	/**  0 for the most recent stash. */
	index: number,
	/**  `stash@{0}`. */
	name: string,
	/**  Stash message, e.g. `WIP on main: 3f9c2a1 fix: …`. */
	message: string,
	/**  The stash commit. */
	sha: string,
	/**  The commit the stash was made on (first parent of the stash commit). */
	baseSha: string,
	/**
	 *  Commit holding the untracked files (third parent, `--include-untracked`): diffing the
	 *  stash against its base does not show them.
	 */
	untrackedSha: string | null,
	/**  Row of `baseSha` in the graph, when known. */
	row: number | null,
};

/**  The worktree, index or operation state changed (debounced): refetch `repo_state` / status. */
export type StatusChanged = {
	repoId: number,
};

export type SubmoduleRef = {
	name: string,
	/**  Path relative to the worktree root. */
	path: string,
	url: string | null,
	/**  Commit recorded in the index of the superproject, `None` if not recorded. */
	sha: string | null,
	/**  The submodule is checked out (has its own repository). */
	initialized: boolean,
};

/**
 *  Live state of one submodule, next to its `SubmoduleRef` (same `path`). Separate from the
 *  refs listing: knowing whether a submodule has local changes runs a status inside it.
 */
export type SubmoduleStatus = {
	/**  Path relative to the worktree root, as in `SubmoduleRef::path`. */
	path: string,
	/**  Absolute path of the submodule's working tree, to open it in a tab. */
	absolutePath: string,
	/**  Commit recorded by the superproject (its index), `None` if not recorded. */
	expected: string | null,
	/**  Commit checked out in the submodule, `None` when it is not initialized. */
	head: string | null,
	/**  The submodule is cloned and checked out. */
	initialized: boolean,
	/**  The submodule's working tree or index has changes (untracked files included). */
	dirty: boolean,
};

/**  `git submodule update` on some or all submodules. */
export type SubmoduleUpdateRequest = {
	/**  Submodule paths (`SubmoduleRef::path`); empty for every submodule. */
	paths: string[],
	/**  `--init`: clone and register the submodules not initialized yet. */
	init: boolean,
	/**  `--recursive`: also the submodules of the submodules. */
	recursive: boolean,
};

export type Tab = {
	/**  Frontend-generated stable id. */
	id: string,
	/**  `None` for a "new tab" (welcome screen). */
	repoId: number | null,
	/**  Opaque JSON owned by the frontend (panel sizes…), stored as is. */
	uiState: string | null,
};

export type TabsState = {
	/**  Tabs in display order. */
	tabs: Tab[],
	activeTabId: string | null,
};

/**  Outcome of a tag push. */
export type TagPushResult = {
	/**  Tags created or moved on the remote by this push, sorted. */
	pushed: string[],
	/**  Tags already there, unchanged. */
	upToDate: number,
};

export type TagRef = {
	name: string,
	fullName: string,
	/**  Commit the tag points to (peeled). For a tag on a tree or blob, that object's id. */
	sha: string,
	annotated: boolean,
	/**  First line of the annotation message (annotated tags only). */
	message: string | null,
	row: number | null,
};

/**  What the Terminal button and shortcut open. */
export type TerminalMode = 
/**  The panel at the bottom of the repository view (F-267). */
"integrated" | 
/**  The system terminal, or the configured one (F-266). */
"external";

export type TextDiff = {
	hunks: DiffHunk[],
	additions: number,
	deletions: number,
	oldEncoding: TextEncoding,
	newEncoding: TextEncoding,
	oldLineEnding: LineEnding,
	newLineEnding: LineEnding,
	/**  The last line of the side has no terminating newline (`\ No newline at end of file`). */
	oldMissingNewline: boolean,
	newMissingNewline: boolean,
	/**  Line count of each side, for the "whole file" toggle and gutters. */
	oldLineCount: number,
	newLineCount: number,
};

/**  How a side was decoded for display. */
export type TextEncoding = "utf8" | 
/**  Not valid UTF-8: decoded as Windows-1252, a guess the UI must flag. */
"windows1252";

export type ThemePreference = "light" | "dark" | "system";

/**
 *  Visual style (spec §7): `Terminal` is the dense monospace dark style (D), which ignores
 *  the light / dark choice.
 */
export type ThemeStyle = "standard" | "terminal";

/**  Why a diff or merge tool cannot be used. */
export type ToolIssue = 
/**  No tool named, and `diff.tool` / `merge.tool` is not set. */
"notConfigured" | 
/**  Git knows the tool but it is not installed. */
"notInstalled" | 
/**  Git does not know the tool and no `<family>tool.<name>.cmd` defines it. */
"unknown";

/**  Why an operation cannot be undone (or redone) now. */
export type UndoBlock = 
/**
 *  Push, or deletion of a remote branch / tag: the remote has it, an undo here would not
 *  change it.
 */
{ kind: "published" } | 
/**  Fetch with prune: the deleted remote-tracking branches only come back with a fetch. */
{ kind: "pruned" } | 
/**  Pull: what it fetched cannot be put back locally. */
{ kind: "pulled" } | 
/**  The state before the operation could not be recorded (e.g. conflicts in the index). */
{ kind: "notRecorded" } | 
/**  LFS objects or submodule commits were downloaded and checked out (M4-5). */
{ kind: "downloaded" } | 
/**  A worktree was removed with its local changes: they are gone (M4-5). */
{ kind: "filesDeleted" } | 
/**
 *  Refs moved since the operation (in a terminal, or by an operation that is not
 *  journaled): full names (`refs/heads/main`, `HEAD`).
 */
{ kind: "diverged"; refs: string[] };

/**  State of the undo / redo buttons of a repository. */
export type UndoState = {
	/**  Latest operation not undone; `None`: nothing to undo in this session. */
	undo: UndoStep | null,
	/**
	 *  Latest undone operation; `None` when nothing was undone, or when an operation was
	 *  journaled since.
	 */
	redo: UndoStep | null,
};

/**  What `undo` or `redo` would do now. */
export type UndoStep = {
	entry: JournalEntry,
	/**
	 *  Why it would be refused: the entry's own `blocked`, or `diverged` when refs moved
	 *  since. Local changes it would overwrite are only found when it runs
	 *  (`undoWouldOverwrite`).
	 */
	blocked: UndoBlock | null,
};

export type UpstreamState = {
	/**  Short name of the tracking branch, e.g. `origin/main`. */
	name: string,
	/**  Commits on the local branch missing from the upstream. */
	ahead: number,
	/**  Commits on the upstream missing from the local branch. */
	behind: number,
	/**  The upstream is configured but its ref no longer exists (deleted on the remote and pruned). */
	gone: boolean,
};

export type Workspace = {
	id: number,
	name: string,
	/**  Known repos of the workspace, in display order. */
	repoIds: number[],
};

/**  Branch checked out in a new worktree. */
export type WorktreeBranch = 
/**  A local branch not checked out in any worktree. */
{ kind: "existing"; name: string } | 
/**  A new branch created at `start` (a revision: branch, tag, SHA). */
{ kind: "new"; name: string; start: string };

export type WorktreeRef = {
	/**  Absolute path of the worktree. */
	path: string,
	head: HeadState | null,
	/**  The main worktree (the one holding the `.git` folder). */
	isMain: boolean,
	/**  The worktree this session is showing. */
	isCurrent: boolean,
	locked: boolean,
	/**  The worktree folder no longer exists (`git worktree prune` would remove it). */
	prunable: boolean,
};

/**  What removing a worktree would do, for its confirmation. */
export type WorktreeRemovePreview = {
	/**  Absolute path of the worktree, as listed in `WorktreeRef::path`. */
	path: string,
	/**  Branch checked out there: it stays in the repository. */
	branch: string | null,
	/**  Local changes that a forced removal would lose (zero when the folder is missing). */
	dirty: DirtyState,
	locked: boolean,
	/**  The folder no longer exists: removing only forgets the worktree. */
	missing: boolean,
};

/**  Error returned by every fallible command. */
export type YagguiError = {
	code: ErrorCode,
	message: LocalizedText,
	action: ErrorAction | null,
	/**  Raw technical detail (Git stderr, I/O error), shown in a collapsible area. */
	detail: string | null,
	/**  Boxed: rare and large, it would bloat every `Result<_, YagguiError>`. */
	payload: ErrorPayload | null,
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

